export function lookupLocalStoryWord(raw: string): StoryDictEntry | null {
  const cleaned = raw.replace(/[^a-zA-Z'-]/g, '').toLowerCase().trim();
  if (!cleaned) return null;
  if (RAW_ENTRIES[cleaned]) return RAW_ENTRIES[cleaned];

  // Try stripping possessive 's or trailing hyphen punctuation
  const stripped = cleaned.replace(/'s$/, '').replace(/^-+|-+$/g, '');
  if (RAW_ENTRIES[stripped]) return RAW_ENTRIES[stripped];

  return null;
}
